"""Summarize node channel records without modifying the node."""
import json
import os
from pathlib import Path
import re
import stat
import sys


CHANNELS = ("obs", "must")
SEGMENT = re.compile(r"(obs|must)\.([0-9]{12})\.jsonl")


def reject_constant(value):
    raise ValueError("non-JSON constant: " + value)


def integer(value):
    return type(value) is int


def parse_json(data):
    return json.loads(data.decode("utf-8"), parse_constant=reject_constant)


def records(node, channel, entries, bad):
    counts = {}
    files = []
    for name, regular in entries:
        if not regular:
            continue
        match = SEGMENT.fullmatch(name)
        if match and match.group(1) == channel:
            files.append((int(match.group(2)), name))
    files.sort()
    active = channel + ".active.jsonl"
    if (active, True) in entries:
        files.append((None, active))

    for _, name in files:
        parts = (node / name).read_bytes().split(b"\n")
        for line, data in enumerate(parts[:-1], 1):
            try:
                value = parse_json(data)
            except (UnicodeError, ValueError):
                bad.append({"file": name, "line": line, "why": "bad_json"})
                continue
            seq = value.get("seq") if isinstance(value, dict) else None
            if not integer(seq) or seq < 1:
                bad.append({"file": name, "line": line, "why": "no_seq"})
                continue
            counts[seq] = counts.get(seq, 0) + 1
        if parts[-1]:
            bad.append({"file": name, "line": len(parts), "why": "torn"})

    ordered = sorted(counts)
    missing = [[a + 1, b - 1] for a, b in zip(ordered, ordered[1:]) if b > a + 1]
    result = {"count": sum(counts.values()),
              "first": ordered[0] if ordered else None,
              "last": ordered[-1] if ordered else None,
              "missing": missing,
              "dup": [seq for seq in ordered if counts[seq] >= 2],
              "next_seq": None, "unacked": None, "stale_next": None}
    return result, counts


def apply_state(node, channels, counts, bad):
    try:
        data = (node / "state.json").read_bytes()
    except FileNotFoundError:
        return
    except OSError:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return
    try:
        state = parse_json(data)
    except (UnicodeError, ValueError):
        state = None
    if not isinstance(state, dict) or not isinstance(state.get("channels"), dict):
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
        return

    invalid = False
    for channel in CHANNELS:
        fields = state["channels"].get(channel)
        required = ("next_seq", "acked_upto") if channel == "must" else ("next_seq",)
        if not isinstance(fields, dict) or any(not integer(fields.get(key)) for key in required):
            invalid = True
            continue
        summary = channels[channel]
        next_seq = fields["next_seq"]
        summary["next_seq"] = next_seq
        if channel == "must":
            summary["unacked"] = sum(seq > fields["acked_upto"] for seq in counts[channel])
        if summary["last"] is not None:
            summary["stale_next"] = next_seq != summary["last"] + 1
    if invalid:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})


def summarize(node):
    with os.scandir(node) as listing:
        entries = [(entry.name, stat.S_ISREG(entry.stat(follow_symlinks=False).st_mode))
                   for entry in listing]
    bad = []
    channels = {}
    counts = {}
    for channel in CHANNELS:
        channels[channel], counts[channel] = records(node, channel, entries, bad)
    apply_state(node, channels, counts, bad)
    bad.sort(key=lambda item: (item["file"], item["line"] or 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    argv = sys.argv if argv is None else argv
    if len(argv) != 2:
        return 2
    node = Path(argv[1])
    if not node.is_dir():
        return 2
    try:
        result = summarize(node)
    except OSError:
        return 2
    print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
